        resources = path

    if not targets:
        targets = collect(("unclaimed_territory", "territory", "frontier", "neutral_cells"))

    moves = [(0, 0), (1, 0), (-1, 0), (0, 1), (0, -1)]
    legal = []
    for dx, dy in moves:
        nx, ny = sx + dx, sy + dy
        if clamp_move(nx, ny, w, h, blocked):
            legal.append((dx, dy, nx, ny))

    if not legal:
        return [0, 0]

    def md(ax, ay, bx, by):
        return abs(ax - bx) + abs(ay - by)

    # Primary attraction targets.
    goal_list = resources if resources else targets

    # If opponent is nearby, bias toward safety unless we have a clear objective.
    opp_d = md(sx, sy, ox, oy)
    danger = opp_d <= 2

    best = None
    best_score = None

    cx = (w - 1) / 2 if w else 0
    cy = (h - 1) / 2 if h else 0

    for dx, dy, nx, ny in legal:
