        # Objective seeking.
        if goal_list:
            d0 = 10 ** 9
            d1 = 10 ** 9
            for tx, ty in goal_list:
                d = md(sx, sy, tx, ty)
                if d < d0:
                    d0 = d
                dn = md(nx, ny, tx, ty)
                if dn < d1:
                    d1 = dn
            score += (d0 - d1) * 8

        # Opponent interaction: flee when close, otherwise slightly pressure.
        nd_opp = md(nx, ny, ox, oy)
        score += (nd_opp - opp_d) * (6 if danger else 1)

        # Prefer central, mobile positions in unknown tasks.
        score -= abs(nx - cx) * 0.2 + abs(ny - cy) * 0.2

        # Mild penalty for waiting unless already best.
        if dx == 0 and dy == 0:
            score -= 0.5

        # Avoid hugging walls when no objective.
        if not goal_list:
            edge = 0
            if nx == 0 or nx == w - 1:
                edge += 1
            if ny == 0 or ny == h - 1:
                edge += 1
            score -= edge * 0.7

        if best_score is None or score > best_score or (score == best_score and (dx, dy) < best):
